    cmtPosSizeTitle: 'Position Size Calculator',
    cmtPosSizeIntro: 'Turn a fixed % risk into the exact position size from your entry and stop. This is the single most important number in risk management — size from the stop, never from a round lot.',
    cmtAccount: 'Account Balance',
    cmtRiskPct: 'Risk per Trade (%)',
