  rorTitle: "Risk of Ruin",
  rorIntro: "The probability your account hits a chosen drawdown within 500 trades, given your edge and bet size. Monte Carlo over 5,000 simulated runs with fixed-fractional sizing.",
  rorWinRate: "Win rate",
  rorRiskPct: "Risk per trade",
